'use strict';
// Regional growth uses existing city coordinates unchanged, including old saves.
function cityRegions(){if(S.cityRegions?.length)return S.cityRegions;let regions=[];for(let c of realCities()){let r=regions.find(r=>Math.hypot(c.x-r.x,c.y-r.y)<480);if(!r){r={id:regions.length,x:c.x,y:c.y,name:regions.length?'第'+(regions.length+1)+'城圈':'海岸城圈'};regions.push(r);}c.regionId=r.id;}S.cityRegions=regions;return regions;}
function separatedCityPoint(x,y,cities){return cityBuildable(x,y,2)&&cities.every(c=>Math.hypot(c.x-x,c.y-y)>=190&&(Math.abs(c.x-x)>=190||Math.abs(c.y-y)>=145));}
function regionalLocalPoint(region,cities){let members=cities.filter(c=>c.regionId===region.id),anchors=members;if(!anchors.length)return null;for(let i=0;i<350;i++){let anchor=anchors[i%anchors.length],angle=rand(-Math.PI,Math.PI),distance=rand(195,330),x=anchor.x+Math.cos(angle)*distance,y=anchor.y+Math.sin(angle)*distance;if(Math.hypot(x-region.x,y-region.y)>440||!separatedCityPoint(x,y,cities))continue;return {x,y};}return null;}
function regionalCenterPoint(regions,cities){let connected=regions.filter(r=>cities.some(c=>c.regionId===r.id&&cityHasRoute(c)));if(!connected.length)return null;let phase=(regions.length-1)%5,angles=[-2.25,2.25,Math.PI,-Math.PI/2,Math.PI/2];for(let i=0;i<500;i++){let anchor=connected[Math.floor(i/100)%connected.length],angle=angles[(phase+Math.floor(i/25))%angles.length]+rand(-.32,.32),distance=rand(590,760),x=anchor.x+Math.cos(angle)*distance,y=anchor.y+Math.sin(angle)*distance;if(regions.some(r=>Math.hypot(x-r.x,y-r.y)<560)||!separatedCityPoint(x,y,cities))continue;return {x,y};}return null;}
spawnCity=function(){let cities=realCities().filter(c=>!c.removed),regions=cityRegions();if(S.unlocked.includes('rail'))S.farOffered=true;if(cities.length>=48||cities.filter(c=>c.dormant).length>=2)return;let r,p;
for(let region of regions){let members=cities.filter(c=>c.regionId===region.id),target=region.id===0?6:4;if(members.length>=target||region.id>0&&S.day<(region.nextLocalAt??Infinity))continue;p=regionalLocalPoint(region,cities);if(p){r=region;break;}}
let newRegion=false;if(!p){if(!S.unlocked.includes('rail')||regions.some(r=>r.id>0&&cities.filter(c=>c.regionId===r.id).length<4)||cities.some(c=>c.remote&&!cityHasRoute(c)))return;p=regionalCenterPoint(regions,cities);if(!p)return;r={id:regions.length,x:p.x,y:p.y,name:['海岸城圈','北麓城圈','南川城圈','西原城圈','云岭城圈','远山城圈'][regions.length]||'第'+(regions.length+1)+'城圈'};r.discoveredAt=S.day;r.nextLocalAt=S.day+10;regions.push(r);newRegion=true;}
let c=makeCity(p.x,p.y,0,Math.floor(rand(0,4)),cities.length%3);Object.assign(c,{name:names[cities.length%names.length]+(r.id?'·'+r.name:''),regionId:r.id,dormant:true,openingAt:S.day+2.5,grace:0});if(r.id>0){Object.assign(c,{remote:true,remoteStage:Math.min(3,r.id-1),regionalGrowth:true,discoveredAt:S.day});if(!newRegion)r.nextLocalAt=S.day+10;}S.cities.push(c);if(r.id>0)S.farOffered=true;toast(newRegion?'发现 '+r.name+' · 周边城镇将随时间逐步出现':'发现 '+c.name+' · '+r.name+'内扩展');};
const climateBeforeRegions=drawClimate;
drawClimate=function(){let regions=cityRegions();for(let r of regions){let members=realCities().filter(c=>c.regionId===r.id&&!c.removed);if(members.length<2)continue;let x=(Math.min(...members.map(c=>c.x))+Math.max(...members.map(c=>c.x)))/2,y=(Math.min(...members.map(c=>c.y))+Math.max(...members.map(c=>c.y)))/2,rx=Math.max(180,...members.map(c=>Math.abs(c.x-x)+100)),ry=Math.max(170,...members.map(c=>Math.abs(c.y-y)+120));ctx.save();ctx.strokeStyle='#8da18b38';ctx.lineWidth=1/Math.max(.4,view.scale);ctx.setLineDash([8,12]);ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);text(r.name,x,y-ry-12,11,'#8a9b83');ctx.restore();}climateBeforeRegions();drawQuakeEffect();};
// Double-ended train sets: use a common centre and fixed track orientation.
// Changing dir reverses the car indices, never the set's physical footprint.
function trainCarriagePoses(v,spacing){let l=vehicleLine(v);if(!l)return [];let lengths=[0];for(let i=1;i<l.stops.length;i++){let a=S.cities[l.stops[i-1]],b=S.cities[l.stops[i]];lengths.push(lengths.at(-1)+Math.hypot(b.x-a.x,b.y-a.y));}let next=v.index+v.dir;if(next<0||next>=l.stops.length)next=v.index-v.dir;let phase=v.dwell>0?0:travelPhase(v.t),position=lengths[v.index]+(lengths[next]-lengths[v.index])*phase,range=serviceRange(v,l),lo=lengths[Math.min(range.lo,v.index)],hi=lengths[Math.max(range.hi,v.index)],half=Math.min((v.cars-1)*spacing/2,Math.max(0,(hi-lo)/2)),centreAt=index=>index===Math.min(range.lo,v.index)?lo+half:index===Math.max(range.hi,v.index)?hi-half:lengths[index],centre=centreAt(v.index)+(centreAt(next)-centreAt(v.index))*phase,step=v.cars>1?half*2/(v.cars-1):0;
return Array.from({length:v.cars},(_,i)=>{let distance=Math.max(0,Math.min(lengths.at(-1),centre+v.dir*(half-i*step))),j=1;while(j<lengths.length-1&&lengths[j]<distance)j++;let a=S.cities[l.stops[j-1]],b=S.cities[l.stops[j]],t=(distance-lengths[j-1])/(lengths[j]-lengths[j-1]||1),p=lanePoint(a,b,l,t),q=lanePoint(a,b,l,Math.min(1,t+.003)),before=lanePoint(a,b,l,Math.max(0,t-.003));return {...p,l,ang:Math.atan2(q.y-before.y,q.x-before.x)};});}
const carriageBeforeDoubleCab=carriagePose;
carriagePose=function(v,index,spacing){return isTrain(v.type)?trainCarriagePoses(v,spacing)[index]:carriageBeforeDoubleCab(v,index,spacing);};
// Road deck, dashed lanes and guard rails; track deck, sleepers and trusses.
function bridgeAppearance(type){return type==='bus'?'road':'rail';}
drawBridges=function(){for(let b of S.bridges){if(b.status==='removed')continue;let a=S.cities[b.heads[0]],z=S.cities[b.heads[1]];if(!a||!z)continue;let length=Math.hypot(z.x-a.x,z.y-a.y),rail=bridgeAppearance(b.type)==='rail',width=rail?14:17;ctx.save();ctx.translate(a.x,a.y);ctx.rotate(Math.atan2(z.y-a.y,z.x-a.x));ctx.globalAlpha=b.status==='open'?1:.5;roundBody(0,-width/2,length,width,2,rail?'#d6ded6':'#a8b2a9','#768e83',1);ctx.strokeStyle=rail?'#4c6866':'#f9f4d7';ctx.lineWidth=rail?1.5:1;ctx.setLineDash(rail?[]:[9,7]);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(length,0);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=rail?'#5d7873':'#eef2de';for(let side of [-1,1]){ctx.beginPath();ctx.moveTo(0,side*(width/2-1));ctx.lineTo(length,side*(width/2-1));ctx.stroke();}if(rail){for(let x=5;x<length;x+=9){ctx.beginPath();ctx.moveTo(x,-4);ctx.lineTo(x,4);ctx.stroke();}for(let x=0;x<length;x+=36){let end=Math.min(length,x+36),mid=(x+end)/2;ctx.beginPath();ctx.moveTo(x,-8);ctx.lineTo(mid,-19);ctx.lineTo(end,-8);ctx.moveTo(mid,-19);ctx.lineTo(mid,8);ctx.stroke();}}else{ctx.fillStyle='#708b7b';for(let x=12;x<length;x+=38){ctx.fillRect(x,-12,4,5);ctx.fillRect(x,7,4,7);}}ctx.restore();for(let c of [a,z]){ctx.save();ctx.fillStyle='#fffdf1';ctx.strokeStyle=rail?'#5d7873':'#9a9e78';ctx.beginPath();if(rail)ctx.rect(c.x-4,c.y-4,8,8);else ctx.arc(c.x,c.y,4,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();}text((rail?'铁路桥':'公路桥')+' #'+b.id,(a.x+z.x)/2,(a.y+z.y)/2+(rail?-25:24),8,rail?'#5d7873':'#8a9278');}if(bridgeDraft?.a&&bridgeDraft.b){let {a,b}=bridgeDraft;ctx.save();ctx.strokeStyle=bridgeTerrainIssue(a,b)?'#ba5e4f':'#c99a58';ctx.lineWidth=5;ctx.setLineDash([6,5]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore();}};
// The earthquake event still uses the established closures, subsidy and odds.
let quakePresentation=null,quakeCamera=null;
const quakeBeforePresentation=triggerQuake;
triggerQuake=function(){let before=new Set(Object.keys(S.blockages));quakeBeforePresentation();let affected=Object.keys(S.blockages).filter(k=>!before.has(k)&&S.blockages[k].cause==='quake');if(!affected.length)return;let points=affected.map(k=>{let ids=k.split('-').slice(-2).map(Number),a=S.cities[ids[0]],b=S.cities[ids[1]];return {x:(a.x+b.x)/2,y:(a.y+b.y)/2};}),event={day:S.day,x:points.reduce((n,p)=>n+p.x,0)/points.length,y:points.reduce((n,p)=>n+p.y,0)/points.length,edges:affected};S.lastEarthquake=event;quakePresentation={...event,at:performance.now()};if(S.quakeAutoFocus!==false&&!pointers.size&&!draft&&!bridgeDraft)focusEarthquake();save();toast('地震影响 '+affected.length+' 段线路 · 车辆安全驶离后封闭，请在工程面板维修');};
function focusEarthquake(){let e=S.lastEarthquake;if(!e)return;let band=fitBand(),scale=Math.max(view.scale,Math.min(portraitMode?.72:1,Math.min(W-50,band.bottom-band.top)/460)),target={scale,x:W/2+(view.rot?e.y:-e.x)*scale,y:(band.top+band.bottom)/2-(view.rot?e.x:e.y)*scale};quakeCamera={from:{...view},target,at:performance.now()};}
function toggleQuakeFocus(){S.quakeAutoFocus=S.quakeAutoFocus===false;save();showEngineering();}
function drawQuakeEffect(){let e=S.lastEarthquake;if(!e)return;let active=e.edges.filter(k=>S.blockages[k]),age=quakePresentation?(performance.now()-quakePresentation.at)/1000:100;if(!active.length&&age>6)return;ctx.save();for(let key of active){let ids=key.split('-').slice(-2).map(Number),a=S.cities[ids[0]],b=S.cities[ids[1]],block=S.blockages[key];if(!a||!b)continue;ctx.save();ctx.strokeStyle=block.status==='repairing'?'#6d9c8b':block.status==='pending'?'#c69b50':'#c77d58';ctx.lineWidth=8;ctx.globalAlpha=.5;ctx.setLineDash(block.status==='repairing'?[5,6]:[3,8]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore();}ctx.strokeStyle='#c37149';ctx.fillStyle='#ce72451a';ctx.lineWidth=2/Math.max(view.scale,.4);for(let i=0;i<3&&age<5;i++){let r=30+((age*.32+i/3)%1)*155;ctx.globalAlpha=(1-(r-30)/155)*.65;ctx.beginPath();ctx.arc(e.x,e.y,r,0,Math.PI*2);ctx.stroke();}ctx.globalAlpha=.9;ctx.beginPath();ctx.arc(e.x,e.y,12,0,Math.PI*2);ctx.fill();ctx.stroke();text('震中 · '+active.length+'段待恢复',e.x,e.y-24,11,'#b16e4d');ctx.restore();}
const engineeringBeforeQuake=showEngineering;
showEngineering=function(){engineeringBeforeQuake();let e=S.lastEarthquake,summary=e?`<b>最近地震 · 第${Math.floor(e.day)+1}天</b><p>${e.edges.filter(k=>S.blockages[k]).length} / ${e.edges.length}段尚未恢复。封闭前会等待在途车辆驶离，维修耗时沿用原规则。</p><button onclick="closeModal();focusEarthquake()">定位震区</button>`:'<b>地震监测</b><p>发生后显示震中、受损路段和维修状态。</p>';$('modal-content').innerHTML+=`<section class="quake-summary">${summary}<button onclick="toggleQuakeFocus()">自动聚焦震区：${S.quakeAutoFocus===false?'关':'开'}</button></section>`;};
const renderBeforeQuakeCamera=render;
render=function(){let now=performance.now();if(quakeCamera){if(pointers.size||draft||bridgeDraft)quakeCamera=null;else if(!modalOpen){let t=Math.min(1,(now-quakeCamera.at)/650),k=t*t*(3-2*t);for(let key of ['scale','x','y'])view[key]=quakeCamera.from[key]+(quakeCamera.target[key]-quakeCamera.from[key])*k;if(t>=1)quakeCamera=null;}}let reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches,age=quakePresentation?(now-quakePresentation.at)/1000:100,dx=0,dy=0;if(age<1.2&&!reduced&&!pointers.size&&!modalOpen){let strength=(1-age/1.2)*2.5;dx=Math.sin(age*81)*strength;dy=Math.cos(age*67)*strength;}view.x+=dx;view.y+=dy;try{return renderBeforeQuakeCamera();}finally{view.x-=dx;view.y-=dy;}};
cv.addEventListener('pointerdown',()=>{quakeCamera=null;},{passive:true});cv.addEventListener('wheel',()=>{quakeCamera=null;},{passive:true});
// Continue the same coast and river beyond the old background texture; caches
// stay fixed-size instead of allocating a canvas as large as the expanding map.
const terrainBeforeExpansion=drawTerrain;
drawTerrain=function(){let {left,top,right,bottom}=worldViewportRect(20);ctx.save();ctx.fillStyle='#faf9f2';ctx.fillRect(left,top,right-left,bottom-top);let traceCoast=offset=>{ctx.beginPath();for(let y=top;y<=bottom+12;y+=12){let x=coast(y)+offset;if(y===top)ctx.moveTo(x,y);else ctx.lineTo(x,y);}};traceCoast(0);ctx.lineTo(right,bottom+12);ctx.lineTo(right,top);ctx.closePath();let sea=ctx.createLinearGradient(980,0,1420,0);sea.addColorStop(0,'#d4e7e6');sea.addColorStop(.35,'#e0eded');sea.addColorStop(1,'#edf4f2');ctx.fillStyle=sea;ctx.fill();ctx.save();ctx.clip();for(let [offset,width,color] of [[12,26,'#c3deda'],[45,35,'#cfe4e1']]){traceCoast(offset);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}ctx.restore();for(let [offset,width,color] of [[-3,5,'#e8dfc2'],[0,1.2,'#93b8b0']]){traceCoast(offset);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}ctx.lineCap='round';ctx.beginPath();for(let y=top;y<=bottom+12;y+=12){if(y===top)ctx.moveTo(river(y),y);else ctx.lineTo(river(y),y);}for(let [width,color] of [[34,'#e6ecdb'],[24,'#cddbc4'],[19,'#94bdb9'],[16,'#b8d9d5'],[10,'#d1e8e2']]){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}ctx.restore();terrainBeforeExpansion();};
snapBank=function(p){let side=pointBank(p),y=p.y;return {x:river(y)+side*19,y,side};};

const helpBeforeUpgrade=help;help=function(){helpBeforeUpgrade();$('modal-content').innerHTML+='<section class="infra-card"><h3>每日行情与网络扩展</h3><p>金融市场 → 我的持仓，可指定股数卖出或全部卖出。证券公司开市后，每天09:00自动显示一次股票简报，并暂停整个交通世界；关闭或点击继续后，恢复此前的运行状态。</p><p>东、西两图分别开局。新地图先逐步发展当前城市群，再寻找可容纳新城市群的区域；不会按四座城市硬拆圈，也不会把零散远镇算成新圈。原海岸存档继续保留原地形。</p><p>铁路两端均为驾驶室，到终点换端运行。地震发生后自动聚焦震区；可在工程面板关闭自动聚焦、定位震区和安排维修。</p></section>';};
